from pathlib import Path
import shutil, sys, base64

def dec(s):
    return base64.b64decode(s.encode("ascii")).decode("utf-8")

ROOT = Path.cwd()
APP = ROOT / "sentinel-react-frontend" / "src" / "App.jsx"
CSS = ROOT / "sentinel-react-frontend" / "src" / "styles.css"

for p in (APP, CSS):
    if not p.exists():
        print("[ERROR] missing:", p)
        sys.exit(1)

for p in (APP, CSS):
    b = p.with_name(p.name + ".before_global_security_alert_v7")
    if not b.exists():
        shutil.copy2(p, b)
        print("[BACKUP]", b.relative_to(ROOT))

app = APP.read_text(encoding="utf-8")

pairs = [
    (dec(""), dec("")),
    (dec("ICBjb25zdCBbcGFnZSxzZXRQYWdlXT11c2VTdGF0ZSgnb3ZlcnZpZXcnKSxbYXV0b1JlZnJlc2gsc2V0QXV0b1JlZnJlc2hdPXVzZVN0YXRlKHRydWUpLFtyZWZyZXNoS2V5LHNldFJlZnJlc2hLZXldPXVzZVN0YXRlKDApCg=="), dec("ICBjb25zdCBbcGFnZSxzZXRQYWdlXT11c2VTdGF0ZSgnb3ZlcnZpZXcnKSxbYXV0b1JlZnJlc2gsc2V0QXV0b1JlZnJlc2hdPXVzZVN0YXRlKHRydWUpLFtyZWZyZXNoS2V5LHNldFJlZnJlc2hLZXldPXVzZVN0YXRlKDApCiAgY29uc3QgW3NlbGVjdGVkSW5jaWRlbnRJZCxzZXRTZWxlY3RlZEluY2lkZW50SWRdPXVzZVN0YXRlKCcnKQo=")),
    (dec("ICBjb25zdCBsYXRlc3RJbmNpZGVudD1jcml0aWNhbE9wZW5bMF18fGluY2lkZW50c1swXQogIGNvbnN0IHJlZnJlc2g9KCk9PnNldFJlZnJlc2hLZXkoeD0+eCsxKQo="), dec("")),
    (dec(""), dec("")),
    (dec("ICAgIHtwYWdlPT09J2luY2lkZW50cycmJjxJbmNpZGVudHNQYWdlIGluY2lkZW50cz17aW5jaWRlbnRzfSBhbGxFdmVudHM9e2V2ZW50c30gaW5pdGlhbElkPXtsYXRlc3RJbmNpZGVudD8uaWR9Lz59IA=="), dec("ICAgIHtwYWdlPT09J2luY2lkZW50cycmJjxJbmNpZGVudHNQYWdlIGtleT17c2VsZWN0ZWRJbmNpZGVudElkfHxsYXRlc3RJbmNpZGVudD8uaWR8fCdpbmNpZGVudC1wYWdlJ30gaW5jaWRlbnRzPXtpbmNpZGVudHN9IGFsbEV2ZW50cz17ZXZlbnRzfSBpbml0aWFsSWQ9e3NlbGVjdGVkSW5jaWRlbnRJZHx8bGF0ZXN0SW5jaWRlbnQ/LmlkfS8+fSA=")),
]

for old,new in pairs:
    if old in app:
        app = app.replace(old,new,1)

old_alert = dec("")
if old_alert in app:
    app = app.replace(old_alert,"",1)

component_anchor = "function CriticalAlert({incident,onOpen}){"
if "function GlobalSecurityAlert(" not in app:
    idx = app.find(component_anchor)
    if idx < 0:
        raise RuntimeError("CriticalAlert anchor not found")
    app = app[:idx] + dec("") + app[idx:]

APP.write_text(app, encoding="utf-8")
print("[WRITE] App.jsx")

css = CSS.read_text(encoding="utf-8")
marker = "/* ===== GLOBAL SECURITY ALERT V7 ===== */"
if marker not in css:
    CSS.write_text(css + dec(""), encoding="utf-8")
    print("[WRITE] styles.css")

print("SENTINEL Global Security Alert v7 applied")
